//! Addresses individual settings by dotted path, such as `sleep.replay_step_count`.
//!
//! Front ends use this to list and edit every setting without knowing the
//! settings structure, so a newly added setting is editable everywhere at once.

use serde_json::Value;

use crate::configuration::RuntimeSettings;
use crate::error::{BrainError, BrainResult};

const PATH_SEPARATOR: char = '.';

// Defines `SETTING_DESCRIPTIONS`, generated by `build.rs` from the doc comments
// in `settings.rs` so every setting is explained in exactly one place.
include!(concat!(env!("OUT_DIR"), "/setting_descriptions.rs"));

/// One setting: where it lives, what it currently holds, and what it does.
#[derive(Debug, Clone, PartialEq)]
pub struct SettingEntry {
    /// Dotted path, for example `generation.temperature`.
    pub path: String,
    /// The current value as JSON.
    pub value: Value,
    /// What the setting does.
    pub description: &'static str,
}

/// Explains a setting (`sleep.replay_step_count`) or a group of settings (`sleep`).
///
/// Returns an empty string for a path that names neither.
pub fn describe_setting(path: &str) -> &'static str {
    SETTING_DESCRIPTIONS
        .iter()
        .find(|(described_path, _)| *described_path == path)
        .map_or("", |(_, description)| description)
}

impl RuntimeSettings {
    /// Every setting with its current value, ordered by path.
    pub fn entries(&self) -> Vec<SettingEntry> {
        let document = serde_json::to_value(self).unwrap_or(Value::Null);
        let mut entries = Vec::new();
        collect_entries(&document, String::new(), &mut entries);
        entries
    }

    /// Returns a copy with the setting at `path` replaced by `value`.
    ///
    /// Fails when the path does not name a setting or the value has the wrong type.
    pub fn with_entry(&self, path: &str, value: Value) -> BrainResult<Self> {
        let mut document =
            serde_json::to_value(self).map_err(|error| invalid_setting(path, error))?;
        let pointer = format!("/{}", path.replace(PATH_SEPARATOR, "/"));
        let slot = document
            .pointer_mut(&pointer)
            .filter(|slot| !slot.is_object())
            .ok_or_else(|| invalid_setting(path, "no such setting"))?;
        *slot = value;
        serde_json::from_value(document).map_err(|error| invalid_setting(path, error))
    }

    /// Like [`RuntimeSettings::with_entry`], reading the value from text.
    ///
    /// The text is parsed as JSON (`true`, `3`, `0.5`, `["a", "b"]`); anything
    /// that is not valid JSON is taken as a plain string.
    pub fn with_entry_text(&self, path: &str, value_text: &str) -> BrainResult<Self> {
        let value = serde_json::from_str(value_text)
            .unwrap_or_else(|_| Value::String(value_text.to_string()));
        self.with_entry(path, value)
    }
}

/// Walks a JSON document and records every leaf with its dotted path.
fn collect_entries(node: &Value, path: String, entries: &mut Vec<SettingEntry>) {
    let Value::Object(fields) = node else {
        entries.push(SettingEntry {
            description: describe_setting(&path),
            path,
            value: node.clone(),
        });
        return;
    };
    for (field_name, field_value) in fields {
        let field_path = match path.is_empty() {
            true => field_name.clone(),
            false => format!("{path}{PATH_SEPARATOR}{field_name}"),
        };
        collect_entries(field_value, field_path, entries);
    }
}

fn invalid_setting(path: &str, reason: impl std::fmt::Display) -> BrainError {
    BrainError::InvalidConfiguration(format!("setting '{path}': {reason}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_setting_is_listed_with_a_dotted_path() {
        let entries = RuntimeSettings::default().entries();

        let temperature = entries
            .iter()
            .find(|entry| entry.path == "generation.temperature")
            .unwrap();
        assert_eq!(temperature.value, serde_json::json!(0.7));
        assert!(
            entries
                .iter()
                .all(|entry| entry.path.contains(PATH_SEPARATOR))
        );
    }

    #[test]
    fn every_setting_and_every_group_is_explained() {
        let entries = RuntimeSettings::default().entries();

        for entry in &entries {
            assert!(
                !entry.description.is_empty(),
                "{} has no description",
                entry.path
            );
            let group_name = entry.path.split(PATH_SEPARATOR).next().unwrap();
            assert!(
                !describe_setting(group_name).is_empty(),
                "group {group_name} has no description"
            );
        }
        assert_eq!(
            describe_setting("generation.temperature"),
            "Sampling temperature; zero always picks the most likely byte."
        );
        assert_eq!(describe_setting("no.such_setting"), "");
    }

    #[test]
    fn a_setting_can_be_replaced_by_path() {
        let settings = RuntimeSettings::default();

        let changed = settings
            .with_entry_text("sleep.replay_step_count", "7")
            .unwrap();
        let renamed = changed
            .with_entry_text("chat.user_prefix", "User: ")
            .unwrap();
        let blocked = renamed
            .with_entry_text("safety.blocked_phrases", r#"["forget everything"]"#)
            .unwrap();

        assert_eq!(blocked.sleep.replay_step_count, 7);
        assert_eq!(blocked.chat.user_prefix, "User: ");
        assert_eq!(blocked.safety.blocked_phrases, ["forget everything"]);
        assert_eq!(blocked.generation, settings.generation);
    }

    #[test]
    fn unknown_paths_and_wrong_types_are_rejected() {
        let settings = RuntimeSettings::default();

        assert!(
            settings
                .with_entry_text("sleep.no_such_field", "1")
                .is_err()
        );
        assert!(settings.with_entry_text("sleep", "1").is_err());
        assert!(
            settings
                .with_entry_text("sleep.replay_step_count", "many")
                .is_err()
        );
    }
}
